from pathlib import Path
import json,re,datetime
root=Path(__file__).resolve().parents[1];e=root/'evidence'
files=['unit-php83.json','unit-php85.json','integration-php83.json','integration-php85.json','security-php83.json','security-php85.json','extended-php83.json','extended-php85.json','browser.json','accessibility.json','seo.json','concurrency.json','export-readers.json','lifecycle.json']
records=[];coverage={}
for name in files:
 d=json.loads((e/name).read_text())
 for row in d.get('results',d.get('tests',[])):
  records.append((name,row))
  for test in re.findall(r'(?<![A-Z])(?:T\d{2}|I\d{2})',str(row.get('test',row.get('id','')))):
   coverage.setdefault(test,[]).append((name,row['status']))
for test,name in [('T33','zip-install.json'),('T34','zip-install.json'),('T44','store-isolation.json')]:coverage.setdefault(test,[]).append((name,json.loads((e/name).read_text())['status']))
